param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
$output=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path -LiteralPath $output){throw 'Fresh output required'};[IO.Directory]::CreateDirectory($output)|Out-Null
$data=Join-Path $output 'own-preview';$process=$null;$checks=0;$startupSamples=New-Object System.Collections.Generic.List[object]
function Check([bool]$ok,[string]$name){if(-not $ok){throw ('PERSISTENCE_FAIL '+$name)};$script:checks++}
function Await([scriptblock]$test,[string]$name){$end=[DateTime]::UtcNow.AddSeconds(45);do{if(&$test){return};if($process.HasExited){throw ('EXIT '+$name)};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow -lt $end);throw ('TIMEOUT '+$name)}
function Find([string]$id){return $script:root.FindFirst([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::AutomationIdProperty,$id))}
function Click([string]$id){Await {$e=Find $id;return $e -and $e.Current.IsEnabled -and -not $e.Current.IsOffscreen} $id;(Find $id).GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke()}
function StartOwn{$start=[Diagnostics.ProcessStartInfo]::new([IO.Path]::GetFullPath($Executable));$start.UseShellExecute=$false;$start.WindowStyle='Hidden';$start.Arguments='--data-dir "'+$data+'"';$clock=[Diagnostics.Stopwatch]::StartNew();$script:process=[Diagnostics.Process]::Start($start);Await {$process.Refresh();$process.MainWindowHandle -ne [IntPtr]::Zero} 'own hwnd';$script:root=[Windows.Automation.AutomationElement]::FromHandle($process.MainWindowHandle);Await {$null -ne (Find 'LibraryOpen')} 'interactive startup';$startupSamples.Add(@{run=$startupSamples.Count+1;interactiveStartupMs=$clock.Elapsed.TotalMilliseconds;scope='fresh process; first then second launch same private profile; uncontrolled OS cache; no diagnostics or XAML capture'})}
try{
 StartOwn;Click 'LibraryOpen';Await {$null -ne (Find 'GalleryCount')} 'empty own library';Await {(Find 'GalleryCount').Current.Name -like '0 项*'} 'no demo mixed into own library';Check (-not (Test-Path -LiteralPath (Join-Path $data 'window-state.json'))) 'normal mode no diagnostics dump'
 $pointer=Get-Content -LiteralPath (Join-Path $data 'winui-library-v1.json') -Raw
 $import=Join-Path $output 'synthetic-images';[IO.Directory]::CreateDirectory($import)|Out-Null;$image=Join-Path $import 'owned-synthetic.png';Copy-Item -LiteralPath (Join-Path (Split-Path -Parent $Executable) 'Assets/Stage2/alpine.png') -Destination $image;$hash=(Get-FileHash -LiteralPath $image -Algorithm SHA256).Hash
 Click 'GalleryImportPathToggle';(Find 'GalleryImportPath').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).SetValue($import);Click 'GalleryImportStart';Await {$null -ne (Find 'ManageList')} 'task center';Start-Sleep -Milliseconds 400;Click 'NavGallery';Click 'GalleryRefresh';Await {(Find 'GalleryCount').Current.Name -like '1 项*'} 'explicit import'
 Click 'ClosePreview';Check ($process.WaitForExit(30000) -and $process.ExitCode -eq 0) 'safe first close';Check ((Get-FileHash -LiteralPath $image -Algorithm SHA256).Hash -eq $hash) 'original unchanged';Check (Test-Path -LiteralPath (Join-Path $data 'winui-window-v1.json')) 'separate WinUI geometry'
 StartOwn;Click 'LibraryOpen';Await {$null -ne (Find 'GalleryCount')} 'reopen';Await {(Find 'GalleryCount').Current.Name -like '1 项*'} 'index persisted';Check ((Get-Content -LiteralPath (Join-Path $data 'winui-library-v1.json') -Raw) -eq $pointer) 'same persistent preview pointer'
 Click 'NavJobs';Await {$null -ne (Find 'ManageList')} 'jobs reopen';Await {(Find 'ManageList').FindAll([Windows.Automation.TreeScope]::Children,[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::ControlTypeProperty,[Windows.Automation.ControlType]::ListItem)).Count -ge 1} 'persistent jobs';Check $true 'job survived UI restart'
 Click 'ClosePreview';Check ($process.WaitForExit(30000) -and $process.ExitCode -eq 0) 'safe second close';Check ((Get-FileHash -LiteralPath $image -Algorithm SHA256).Hash -eq $hash) 'original unchanged after reopen'
 @{result='passed';count=$checks;startupSamples=$startupSamples.ToArray();syntheticOnly=$true;privateDataAccess=$false}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $output 'management-persistence-report.json');Write-Output ('MANAGEMENT_PERSISTENCE_PASSED '+$checks)
}finally{if($process -and -not $process.HasExited){$process.CloseMainWindow()|Out-Null;$process.WaitForExit(30000)|Out-Null}}
